"""One synthetic live caller→gateway→cognitive-ledger parity check."""
import json, os, sys
from pathlib import Path
from syune.model_gateway import *
MODEL="gpt-5.4-mini-2026-03-17"
def main(out):
 out=Path(out);out.mkdir(parents=True,exist_ok=True);caps=ModelCapabilities(frozenset({Capability.TEXT_GENERATION,Capability.STRUCTURED_OUTPUT,Capability.NATIVE_JSON_SCHEMA,Capability.USAGE_TELEMETRY,Capability.PROVIDER_REQUEST_ID}),400000,128000);meta=ModelMetadata("openai",MODEL,"2026-03-17",caps,.75,4.5);store=EvidenceStore(out/"gateway.db");gateway=ModelGateway({"openai":OpenAIResponsesAdapter(os.environ["OPENAI_API_KEY"],{MODEL:meta})},store,routes=(("openai",MODEL),));ledger=CognitiveTransactionLedger(out/"cognitive.db");ledger.db.execute("create table effects(k text primary key,v text)");schema={"type":"object","additionalProperties":False,"properties":{"decision":{"type":"string","enum":["ABSTAIN"]}},"required":["decision"]};req=ModelExecutionRequest("phase30:live:verification:1","Synthetic P0 integration validation",({"role":"system","content":"Return the required synthetic decision only."},{"role":"user","content":"For this non-sensitive test choose ABSTAIN."}),call_role=CallRole.VERIFICATION,structured_output_schema=schema,preferred_model=MODEL,exact_model=True,principal="phase30-validator",data_policy=DataPolicy(allow_external=True,allowed_providers=frozenset({"openai"})),budget_limits=(BudgetLimit("experiment","phase30-live",max_calls=1,max_input_tokens=1000,max_output_tokens=64,max_cost_usd=.02),),max_output_tokens=64,retry_policy=RetryPolicy(max_attempts=1));op=CognitiveOperation("live-verification-1","verification","phase30-validator",req.purpose,(),req);result=GatewayCognitiveTransactionService(gateway,ledger).execute(op,lambda db,v:(db.execute("insert into effects values('live-1',?)",(v["decision"],)),v)[1]);audit=ledger.audit(result.cognitive_transaction_id);report={"model":MODEL,"gateway_commits":store.db.execute("select count(*) from commits").fetchone()[0],"cognitive_commits":ledger.db.execute("select count(*) from cognitive_transactions where state='APPLIED'").fetchone()[0],"effects":ledger.db.execute("select count(*) from effects").fetchone()[0],"decision":result.value["decision"],"cost_usd":audit["cost_usd"],"audit_linked":audit["gateway_semantic_commit_id"]==result.gateway_semantic_commit_id};(out/"report.json").write_text(json.dumps(report,indent=2)+"\n");print(json.dumps(report));ledger.close();store.close()
if __name__=="__main__":main(sys.argv[1])
